  "Samples~/Basic/GamealiaSample.cs": '// Gamealia SDK sample: attach to any GameObject in your first scene.\n// In the Editor every call answers with local fallbacks (mock init, no ads, PlayerPrefs data).\n\nusing System;\nusing UnityEngine;\n\npublic class GamealiaSample : MonoBehaviour\n{\n    [Serializable]\n    class SaveData\n    {\n        public int level = 1;\n        public int coins;\n    }\n\n    SaveData save = new SaveData();\n    bool saveLoaded;\n\n    void Start()\n    {\n        Gamealia.OnAdStart += () => Time.timeScale = 0f; // audio is muted automatically (Gamealia.AutoMuteAudio)\n        Gamealia.OnAdEnd += () => Time.timeScale = 1f;\n        Gamealia.OnPause += () => Time.timeScale = 0f;\n        Gamealia.OnResume += () => Time.timeScale = 1f;\n        Gamealia.OnUserChange += user => Debug.Log(user != null ? "Signed in as " + user.username : "Signed out");\n        Gamealia.OnRoomJoin += code => JoinRoom(code);\n\n        Gamealia.Init(info =>\n        {\n            Debug.Log($"Gamealia: env={info.environment} locale={info.locale} device={info.device}");\n            // Pick your UI language from info.locale ("es", "en", ...).\n\n            Gamealia.Data.Load(r =>\n            {\n                // ok=false means the save could not be read: keep defaults and do not overwrite it.\n                saveLoaded = r.ok;\n                if (r.ok) Gamealia.Data.Get<SaveData>("save", s => { if (s != null) save = s; Ready(); });\n                else Ready();\n            });\n        });\n    }\n\n    void Ready()\n    {\n        Gamealia.Game.LoadingStop(); // required, once the game is playable\n\n        var invited = Gamealia.Room.GetJoinCode();\n        if (invited != null) JoinRoom(invited);\n    }\n\n    // Call when a level starts / ends.\n    public void StartLevel() => Gamealia.Game.GameplayStart();\n\n    public void FinishLevel()\n    {\n        Gamealia.Game.GameplayStop();\n        Gamealia.Game.HappyTime();\n        save.level++;\n        if (saveLoaded) Gamealia.Data.Set("save", save, ok => { if (!ok) Debug.LogWarning("Save rejected"); });\n        Gamealia.Presence.SetStatus("Level " + save.level);\n\n        // A natural break: show a midgame ad, then continue. "Not shown" is normal.\n        Gamealia.Ad.RequestMidgame(shown => StartLevel());\n    }\n\n    // A button the player pressed: "Watch an ad for 50 coins".\n    public void WatchAdForCoins()\n    {\n        Gamealia.Ad.RequestRewarded((shown, rewarded) =>\n        {\n            if (rewarded) save.coins += 50;\n        });\n    }\n\n    public void SignIn()\n    {\n        Gamealia.User.RequestLogin(user =>\n        {\n            if (user == null) return;\n            Gamealia.User.GetToken(token => { /* send token to your server; verify it with the JWKS */ });\n        });\n    }\n\n    // Multiplayer: publish a room and invite friends.\n    public void HostRoom()\n    {\n        var code = Guid.NewGuid().ToString("N").Substring(0, 6).ToUpperInvariant();\n        Gamealia.Room.Publish(new Gamealia.RoomInfo { code = code, name = "My room", players = 1, max = 4, inProgress = false });\n        Gamealia.Room.ShowInvite(code);\n        Gamealia.Room.InviteLink(code, link => GUIUtility.systemCopyBuffer = link);\n    }\n\n    void JoinRoom(string code)\n    {\n        Debug.Log("Join room " + code); // connect to your own multiplayer backend with this code\n    }\n\n    void OnDestroy() => Gamealia.Room.Unpublish();\n}\n',
  "Samples~/WebGLTemplates/Gamealia/index.html": '<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, height=device-height, initial-scale=1.0, user-scalable=no">\n    <title>{{{ PRODUCT_NAME }}}</title>\n    <!-- Gamealia SDK: must load before the Unity loader so Gamealia.jslib finds window.Gamealia. -->\n    <script src="https://gamealia.app/sdk/v1.js"></script>\n    <style>\n      html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #000; }\n      #unity-canvas { display: block; width: 100%; height: 100%; }\n    </style>\n  </head>\n  <body>\n    <canvas id="unity-canvas" tabindex="-1"></canvas>\n    <script>\n      // Report loading as early as possible (Unity builds take a while to download).\n      if (window.Gamealia) {\n        window.Gamealia.init();\n        window.Gamealia.game.loadingStart();\n      }\n      var buildUrl = "Build";\n      var config = {\n        dataUrl: buildUrl + "/{{{ DATA_FILENAME }}}",\n        frameworkUrl: buildUrl + "/{{{ FRAMEWORK_FILENAME }}}",\n#if USE_THREADS\n        workerUrl: buildUrl + "/{{{ WORKER_FILENAME }}}",\n#endif\n        codeUrl: buildUrl + "/{{{ CODE_FILENAME }}}",\n#if MEMORY_FILENAME\n        memoryUrl: buildUrl + "/{{{ MEMORY_FILENAME }}}",\n#endif\n#if SYMBOLS_FILENAME\n        symbolsUrl: buildUrl + "/{{{ SYMBOLS_FILENAME }}}",\n#endif\n        streamingAssetsUrl: "StreamingAssets",\n        companyName: {{{ JSON.stringify(COMPANY_NAME) }}},\n        productName: {{{ JSON.stringify(PRODUCT_NAME) }}},\n        productVersion: {{{ JSON.stringify(PRODUCT_VERSION) }}},\n      };\n      var script = document.createElement("script");\n      script.src = buildUrl + "/{{{ LOADER_FILENAME }}}";\n      script.onload = function () {\n        createUnityInstance(document.querySelector("#unity-canvas"), config)\n          .then(function (instance) { window.unityInstance = instance; })\n          .catch(function (message) { console.error(message); });\n      };\n      document.body.appendChild(script);\n    </script>\n  </body>\n</html>\n'
