// ../core/src/cover.ts
var COVER_SIZE = { width: 1200, height: 630 };
var THUMB_SIZE = { width: 512, height: 512 };
var MAX_ASSET_BYTES = 2 * 1024 * 1024;
function imageMime(b) {
  if (b[0] === 137 && b[1] === 80 && b[2] === 78 && b[3] === 71) return "image/png";
  if (b[0] === 255 && b[1] === 216 && b[2] === 255) return "image/jpeg";
  if (b[0] === 82 && b[1] === 73 && b[2] === 70 && b[3] === 70 && b[8] === 87 && b[9] === 69 && b[10] === 66 && b[11] === 80) return "image/webp";
  return null;
}
function sniff(b) {
  const m31 = imageMime(b);
  if (!m31) throw new Error("screenshot must be a png, jpeg or webp image");
  return m31;
}
function drawScript(dataUrl, title) {
  return `(async () => {
  const img = new Image();
  img.src = ${JSON.stringify(dataUrl)};
  await img.decode();
  const title = ${JSON.stringify(title)};
  const MAX = ${Math.floor(MAX_ASSET_BYTES * 0.97)};
  function draw(w, h, scale) {
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    const x = c.getContext("2d");
    x.fillStyle = "#14121f";
    x.fillRect(0, 0, w, h);
    const s = Math.max(w / img.naturalWidth, h / img.naturalHeight);
    const dw = img.naturalWidth * s, dh = img.naturalHeight * s;
    x.drawImage(img, (w - dw) / 2, (h - dh) / 2, dw, dh);
    const g = x.createLinearGradient(0, h * 0.4, 0, h);
    g.addColorStop(0, "rgba(20,18,31,0)");
    g.addColorStop(1, "rgba(20,18,31,0.92)");
    x.fillStyle = g;
    x.fillRect(0, 0, w, h);
    let size = Math.round(h * scale);
    const font = () => (x.font = "800 " + size + "px system-ui, 'Segoe UI', Roboto, sans-serif");
    font();
    while (x.measureText(title).width > w * 0.9 && size > 14) { size -= 2; font(); }
    x.fillStyle = "#ffffff";
    x.textBaseline = "alphabetic";
    x.shadowColor = "rgba(0,0,0,0.55)";
    x.shadowBlur = Math.round(size * 0.25);
    x.fillText(title, Math.round(w * 0.05), Math.round(h - h * 0.08));
    let mime = "image/png";
    let b64 = c.toDataURL(mime).split(",")[1];
    if (b64.length * 0.75 > MAX) { mime = "image/jpeg"; b64 = c.toDataURL(mime, 0.88).split(",")[1]; }
    return { mime, b64 };
  }
  return { cover: draw(${COVER_SIZE.width}, ${COVER_SIZE.height}, 0.12), thumb: draw(${THUMB_SIZE.width}, ${THUMB_SIZE.height}, 0.11) };
})()`;
}
async function generateCover(screenshot, title, o = {}) {
  const mime = sniff(screenshot);
  const dataUrl = `data:${mime};base64,${Buffer.from(screenshot).toString("base64")}`;
  return withDriver(o.driver, async (driver) => {
    const page = await driver.newPage({ viewport: { width: 400, height: 300 }, touch: false });
    try {
      await page.goto("about:blank");
      const r = await page.evaluate(drawScript(dataUrl, title));
      return {
        cover: new Uint8Array(Buffer.from(r.cover.b64, "base64")),
        coverMime: r.cover.mime,
        thumb: new Uint8Array(Buffer.from(r.thumb.b64, "base64")),
        thumbMime: r.thumb.mime
      };
    } finally {
      await page.close();
    }
  });
}

