    unauthorized: "\u0645\u0641\u062A\u0627\u062D API \u0645\u0641\u0642\u0648\u062F \u0623\u0648 \u0645\u0646\u062A\u0647\u064A \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629 \u0623\u0648 \u0645\u0644\u063A\u0649: \u0634\u063A\u0651\u0644 gamealia_login \u0645\u0631\u0629 \u0623\u062E\u0631\u0649.",
    "not-developer": "\u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u0644\u064A\u0633 \u0639\u0636\u0648\u064B\u0627 \u0641\u064A \u0623\u064A \u062D\u0633\u0627\u0628 \u0645\u0637\u0648\u0651\u0631 \u0628\u0639\u062F: \u0627\u0637\u0644\u0628 \u0645\u0646\u0647 \u0625\u0646\u0634\u0627\u0621 \u062D\u0633\u0627\u0628 \u0641\u064A \u0635\u0641\u062D\u0629 /developers \u0641\u064A \u0627\u0644\u0628\u0648\u0627\u0628\u0629 (\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0645\u0639\u0631\u0648\u0636 + \u0634\u0631\u0648\u0637 \u0627\u0644\u0645\u0637\u0648\u0651\u0631\u064A\u0646) \u0623\u0648 \u0642\u0628\u0648\u0644 \u062F\u0639\u0648\u0629\u060C \u062B\u0645 \u0623\u0639\u062F \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629.",
    "needs-developer-profile": "\u0623\u0646\u0634\u0626 \u0645\u0644\u0641 \u0627\u0644\u0645\u0637\u0648\u0651\u0631 (\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0645\u0639\u0631\u0648\u0636 + \u0627\u0644\u0634\u0631\u0648\u0637) \u0641\u064A \u0635\u0641\u062D\u0629 /developers \u0641\u064A \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0648\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649.",
    "not-found": "\u0644\u0645 \u064A\u064F\u0639\u062B\u0631 \u0639\u0644\u064A\u0647 \u0628\u064A\u0646 \u0623\u0644\u0639\u0627\u0628\u0643 \u0623\u0648 \u0646\u0633\u062E\u0643: \u062A\u062D\u0642\u0651\u0642 \u0645\u0646 slug/id (gamealia_list_games \u064A\u0639\u0631\u0636 \u0627\u0644\u0645\u0648\u062C\u0648\u062F).",
    "slug-taken": "\u0647\u0630\u0627 \u0627\u0644\u0640 slug \u062A\u0633\u062A\u062E\u062F\u0645\u0647 \u0644\u0639\u0628\u0629 \u0623\u062E\u0631\u0649: \u0627\u062E\u062A\u0631 \u063A\u064A\u0631\u0647.",
