    "invalid-listing": "\u0635\u0641\u062D\u0629 \u0627\u0644\u0644\u0639\u0628\u0629 \u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u062D\u0642\u0648\u0644 \u063A\u064A\u0631 \u0635\u0627\u0644\u062D\u0629: \u0635\u062D\u0651\u062D\u0647\u0627 \u0648\u0623\u0639\u062F \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629.",
    "version-in-progress": "\u0646\u0633\u062E\u0629 \u0623\u062E\u0631\u0649 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0644\u0639\u0628\u0629 \u0642\u064A\u062F \u0627\u0644\u0631\u0641\u0639 \u0623\u0648 \u0627\u0644\u0627\u062E\u062A\u0628\u0627\u0631: \u0627\u0646\u062A\u0638\u0631\u0647\u0627 (gamealia_get_status)\u060C \u0623\u0648 \u0623\u0639\u062F \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629 \u0645\u0639 waitForPrevious:true. \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u062A\u064A \u062A\u0646\u062A\u0638\u0631 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0644\u0627 \u062A\u0645\u0646\u0639 \u0627\u0644\u0631\u0641\u0639.",
    "illegal-transition": "\u0627\u0644\u0646\u0633\u062E\u0629 \u0644\u064A\u0633\u062A \u0641\u064A \u062D\u0627\u0644\u0629 \u062A\u0633\u0645\u062D \u0628\u0630\u0644\u0643 (\u0645\u062B\u0644\u064B\u0627\u060C \u0644\u0627 \u062A\u064F\u0631\u0633\u0644 \u0644\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0625\u0644\u0627 \u0646\u0633\u062E\u0629 `tested`): \u0631\u0627\u062C\u0639 gamealia_get_status.",
    "game-banned": "\u0647\u0630\u0647 \u0627\u0644\u0644\u0639\u0628\u0629 \u0645\u0648\u0642\u0648\u0641\u0629: \u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u062F\u0639\u0645 Gamealia.",
