    "already-approved": "\u0627\u0633\u062A\u064F\u062E\u062F\u0645 \u0631\u0645\u0632 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0647\u0630\u0627 \u0628\u0627\u0644\u0641\u0639\u0644: \u0634\u063A\u0651\u0644 gamealia_login \u0645\u0631\u0629 \u0623\u062E\u0631\u0649.",
    "login-denied": '\u0631\u0641\u0636 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0641\u064A \u0627\u0644\u0645\u062A\u0635\u0641\u062D ("\u0644\u0633\u062A \u0623\u0646\u0627")\u060C \u0644\u0630\u0627 \u0644\u0645 \u064A\u064F\u0646\u0634\u0623 \u0623\u064A \u0645\u0641\u062A\u0627\u062D. \u0625\u0646 \u0643\u0627\u0646 \u0630\u0644\u0643 \u062E\u0637\u0623\u064B\u060C \u0634\u063A\u0651\u0644 gamealia_login \u0645\u0631\u0629 \u0623\u062E\u0631\u0649 \u0648\u0627\u0637\u0644\u0628 \u0645\u0646\u0647 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629.',
