    "own-login": { description: "\u062A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 \u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644 \u0623\u0648 \u0646\u0638\u0627\u0645 \u062D\u0633\u0627\u0628\u0627\u062A \u062E\u0627\u0635", fix: "\u0623\u0632\u0644 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644\u061B \u0627\u0633\u062A\u062E\u062F\u0645 Gamealia.user.get() / getToken() \u0648\u0627\u0633\u0645\u062D \u0644\u0644\u0636\u064A\u0648\u0641 \u0628\u0627\u0644\u0644\u0639\u0628." },
    broken: { description: "\u0645\u0639\u0637\u0651\u0644\u0629 \u0623\u0648 \u0644\u0627 \u062A\u064F\u062D\u0645\u064E\u0651\u0644 \u0628\u0634\u0643\u0644 \u0635\u062D\u064A\u062D", fix: "\u0634\u063A\u0651\u0644 gamealia_run_autotest \u0645\u062D\u0644\u064A\u064B\u0627 \u0648\u0623\u0635\u0644\u062D \u0627\u0644\u0641\u062D\u0648\u0635\u0627\u062A \u0627\u0644\u0641\u0627\u0634\u0644\u0629 \u0648\u0623\u062E\u0637\u0627\u0621 \u0648\u062D\u062F\u0629 \u0627\u0644\u062A\u062D\u0643\u0645." },
    "misleading-listing": { description: "\u0635\u0641\u062D\u0629 \u0627\u0644\u0644\u0639\u0628\u0629 \u0645\u0636\u0644\u0650\u0651\u0644\u0629 (\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623\u0648 \u0627\u0644\u0648\u0635\u0641 \u0623\u0648 \u0627\u0644\u0635\u0648\u0631)", fix: "\u0627\u062C\u0639\u0644 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0648\u0635\u0641 \u0648\u0627\u0644\u063A\u0644\u0627\u0641 \u0648\u0627\u0644\u0648\u0633\u0648\u0645 \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0644\u0639\u0628\u0629." }
