  noSourceText: "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B1 \u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03BF \u03B3\u03C1\u03B1\u03BC\u03BC\u03AD\u03BD\u03BF \u03B1\u03C0\u03CC \u03C4\u03BF\u03BD developer: \u03B3\u03C1\u03AC\u03C8\u03B5 \u03C4\u03BF\u03C5\u03BB\u03AC\u03C7\u03B9\u03C3\u03C4\u03BF\u03BD \u03BC\u03AF\u03B1 \u03B3\u03BB\u03CE\u03C3\u03C3\u03B1 (\u03C4\u03AF\u03C4\u03BB\u03BF \u03BA\u03B1\u03B9 \u03C0\u03B5\u03C1\u03B9\u03B3\u03C1\u03B1\u03C6\u03AE) \u03BC\u03B5 \u03C4\u03B1 texts \u03C4\u03BF\u03C5 gamealia_update_listing.",
  limitsLine: (t, d, c) => `\u038C\u03C1\u03B9\u03B1: \u03C4\u03AF\u03C4\u03BB\u03BF\u03C2 ${t}, \u03C0\u03B5\u03C1\u03B9\u03B3\u03C1\u03B1\u03C6\u03AE ${d} (\u03AE \u03BA\u03B5\u03BD\u03AE), \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 ${c} (\u03AE \u03BA\u03B5\u03BD\u03CC\u03C2) \u03C7\u03B1\u03C1\u03B1\u03BA\u03C4\u03AE\u03C1\u03B5\u03C2.`,
  machineTag: "\u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B7",
  nextTranslateListing: (slug) => `\u039C\u03B5\u03C4\u03AC\u03C6\u03C1\u03B1\u03C3\u03B5 \u03B5\u03C3\u03CD \u03C4\u03BF \u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03BF \u03C0\u03B7\u03B3\u03AE\u03C2 \u03C3\u03B5 \u03BA\u03AC\u03B8\u03B5 \u03B3\u03BB\u03CE\u03C3\u03C3\u03B1 missing \u03BA\u03B1\u03B9 machine (skill gamealia-translate-listing), \u03BC\u03B5\u03C4\u03AC \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03AD \u03C4\u03B5\u03C2 \u03CC\u03BB\u03B5\u03C2 \u03C3\u03B5 \u03AD\u03BD\u03B1 gamealia_update_listing {game:"${slug}", texts:{<locale>:{title, description, controls}, ...}}`,
  nextReviewMachine: "\u0389 \u03B5\u03BD\u03AD\u03BA\u03C1\u03B9\u03BD\u03B5 \u03BC\u03B9\u03B1 \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B7 \u03BC\u03B5\u03C4\u03AC\u03C6\u03C1\u03B1\u03C3\u03B7 \u03C9\u03C2 \u03AD\u03C7\u03B5\u03B9 \u03BC\u03B5 texts:{<locale>:{}} \u03B1\u03C6\u03BF\u03CD \u03C4\u03B7\u03BD \u03B5\u03BB\u03AD\u03B3\u03BE\u03B5\u03B9 \u03BF developer",
  invalidTexts: (lines) => `\u039A\u03AC\u03C0\u03BF\u03B9\u03B1 \u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03B1 \u03C0\u03B1\u03C1\u03B1\u03B2\u03B9\u03AC\u03B6\u03BF\u03C5\u03BD \u03C4\u03B1 \u03CC\u03C1\u03B9\u03B1 \u03C4\u03B7\u03C2 \u03BA\u03B1\u03C4\u03B1\u03C7\u03CE\u03C1\u03B9\u03C3\u03B7\u03C2\xB7 \u03B4\u03B5\u03BD \u03B1\u03C0\u03BF\u03B8\u03B7\u03BA\u03B5\u03CD\u03C4\u03B7\u03BA\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1:
${lines}`,
  textsWord: "\u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03B1",
  // permissions (microphone/camera)
  permissionsSuggest: "\u0386\u03B4\u03B5\u03B9\u03B5\u03C2 \u03C0\u03BF\u03C5 \u03C0\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03B4\u03B7\u03BB\u03C9\u03B8\u03BF\u03CD\u03BD \u03C3\u03C4\u03B7\u03BD \u03BA\u03B1\u03C4\u03B1\u03C7\u03CE\u03C1\u03B9\u03C3\u03B7 (\u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 getUserMedia):",
  permissionUncertain: "\u03BF\u03B9 \u03C0\u03B5\u03C1\u03B9\u03BF\u03C1\u03B9\u03C3\u03BC\u03BF\u03AF \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03C5\u03C1\u03B9\u03BF\u03BB\u03B5\u03BA\u03C4\u03B9\u03BA\u03BF\u03AF: \u03AD\u03BB\u03B5\u03B3\u03BE\u03B5 \u03C0\u03BF\u03B9\u03B1 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF \u03C4\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9",
  nextDeclarePermissions: (list) => `\u0394\u03AE\u03BB\u03C9\u03C3\u03B5 ${list} \u03C3\u03C4\u03B7\u03BD \u03BA\u03B1\u03C4\u03B1\u03C7\u03CE\u03C1\u03B9\u03C3\u03B7 \u03BC\u03B5 \u03B1\u03B9\u03C4\u03B9\u03BF\u03BB\u03CC\u03B3\u03B7\u03C3\u03B7: gamealia_update_listing {game, permissions:[{name, justification:"why the game needs it"}]}. \u0388\u03BD\u03B1\u03C2 \u03C7\u03B5\u03B9\u03C1\u03BF\u03BA\u03AF\u03BD\u03B7\u03C4\u03BF\u03C2 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03C1\u03AF\u03BD\u03B5\u03B9 \u03BC\u03B1\u03B6\u03AF \u03BC\u03B5 \u03BC\u03B9\u03B1 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7`,
  permNone: "\u03BA\u03B1\u03BC\u03AF\u03B1",
